        ["DescriptorIdentifier is missing or empty."] = "DescriptorIdentifier fehlt oder ist leer.",
        ["DescriptorInfo is in no namespace; Annex J declares {0}."] = "DescriptorInfo steht in keinem Namensraum; Anhang J legt {0} fest.",
        ["DescriptorInfo is in the namespace {0}; Annex J declares {1}."] = "DescriptorInfo steht im Namensraum {0}; Anhang J legt {1} fest.",
        ["DescriptorVersion has no {0}."] = "DescriptorVersion hat kein {0}.",
        ["DescriptorVersion is missing."] = "DescriptorVersion fehlt.",
        ["Descriptors this certificate signs count as trusted from now on. Compare the fingerprint with the one the sender tells you another way, by phone or in person: a Descriptor anyone signed carries a certificate of any name."] = "Descriptoren, die dieses Zertifikat signiert, gelten ab jetzt als vertrauenswürdig. Vergleiche den Fingerabdruck mit dem, den dir der Absender auf anderem Weg nennt, am Telefon oder persönlich: Jeder kann einen Descriptor mit einem Zertifikat beliebigen Namens signieren.",
        ["Draw the chosen type or instance with the levels set."] = "Den gewählten Typ oder die gewählte Instanz mit den eingestellten Ebenen zeichnen.",
        ["Endpoints of the server"] = "Endpunkte des Servers",
        ["Error"] = "Fehler",
        ["Every Descriptor is signed (OPC 10000-83 8.2). The receiver checks the signature and decides whether to trust the certificate."] = "Jeder Descriptor wird signiert (OPC 10000-83 8.2). Der Empfänger prüft die Signatur und entscheidet, ob er dem Zertifikat vertraut.",
        ["Everyone who checks a Descriptor you sign sees this name, for example your organisation or department. The certificate is self-signed and valid for three years; the key stays in your Windows profile."] = "Jeder, der einen von dir signierten Descriptor prüft, sieht diesen Namen, zum Beispiel deine Organisation oder Abteilung. Das Zertifikat ist selbstsigniert und drei Jahre gültig; der Schlüssel bleibt in deinem Windows-Profil.",
        ["Everything a server offers is a node: an object, a variable, a method, a type. Each has a NodeId and is joined to other nodes by references. In the document a node becomes an element or a class."] = "Alles, was ein Server anbietet, ist ein Knoten: ein Objekt, eine Variable, eine Methode, ein Typ. Jeder hat eine NodeId und ist über Referenzen mit anderen Knoten verbunden. Im Dokument wird ein Knoten zu einem Element oder einer Klasse.",
        ["ExternalInterface"] = "ExternalInterface",
        ["For each value of the model, the variable whose path has the same words is proposed. Ticked rows are bound: the element gets the variable's address as its NodeId attribute and a Value attribute, as with Bind to element…."] = "Für jeden Wert des Modells wird die Variable vorgeschlagen, deren Pfad dieselben Wörter hat. Angehakte Zeilen werden gebunden: Das Element bekommt die Adresse der Variable als Attribut NodeId und ein Attribut Value, wie bei An Element binden….",
        ["Find servers"] = "Server finden",
        ["Find servers: ask a discovery server (port 4840 of a computer) which servers it knows, and take an address from the list."] = "Server finden: einen Discovery-Server (Port 4840 eines Rechners) fragen, welche Server er kennt, und eine Adresse aus der Liste übernehmen.",
        ["Find servers…"] = "Server finden…",
        ["Host, host:port or URL; empty for this computer"] = "Host, Host:Port oder URL; leer für diesen Rechner",
        ["From file…"] = "Aus Datei…",
        ["Give the version of OPC UA FX the Descriptor adheres to, such as 1.00.03."] = "Gib die Version von OPC UA FX an, der der Descriptor folgt, etwa 1.00.03.",
        ["Identifier (DescriptorIdentifier)"] = "Kennung (DescriptorIdentifier)",
        ["In the address space, expand MPS500, then ST30_Processing and its ParameterSet, and select the variable PartsProduced."] = "Klappe im Adressraum MPS500 auf, dann ST30_Processing und dessen ParameterSet, und wähle die Variable PartsProduced.",
        ["In the address space, tick MPS500. A tick takes the node with everything below it, as deep as 'depth' says; right click it for less."] = "Hake im Adressraum MPS500 an. Ein Haken übernimmt den Knoten mit allem darunter, so tief wie 'Tiefe' angibt; per Rechtsklick wählst du weniger.",
        ["In the modeler, click + next to ObjectTypes and name a type. Select it: small icons appear beside the shape; click Add a variable."] = "Klicke im Modeler auf + neben ObjectTypes und benenne einen Typ. Wähle ihn aus: Neben der Form erscheinen kleine Symbole; klicke auf 'Variable hinzufügen'.",
        ["InstanceHierarchy"] = "InstanceHierarchy",
        ["InterfaceClass"] = "InterfaceClass",
        ["InternalElement"] = "InternalElement",
        ["InternalLink"] = "InternalLink",
        ["Joins two ExternalInterfaces. Annex A writes a reference between the children of a type this way; Check makes sure only the pairs Annex A allows are joined. Nearest in OPC UA: a reference."] = "Verbindet zwei ExternalInterfaces. Annex A schreibt so eine Referenz zwischen den Kindern eines Typs; Prüfen stellt sicher, dass nur die Paare verbunden sind, die Annex A erlaubt. In OPC UA am nächsten: eine Referenz.",
        ["Kind"] = "Art",
        ["Live: {0}  ·  {1} value(s) followed."] = "Live: {0}  ·  {1} Wert(e) verfolgt.",
        ["Mandatory child '{0}' of '{1}' is missing."] = "Das Mandatory-Kindelement '{0}' von '{1}' fehlt.",
        ["Manual"] = "Anleitung",
        ["Match"] = "Treffer",
        ["Model a value the way the plugin reads it: in the editor's tree, add an InternalElement to an instance hierarchy and name it PartsProduced. A value of a server belongs to an element of its own, not to an attribute; binding gives the element its NodeId and Value attributes."] = "Lege einen Wert so an, wie das Plugin ihn liest: Füge im Baum des Editors einer InstanceHierarchy ein InternalElement hinzu und nenne es PartsProduced. Ein Wert eines Servers gehört zu einem eigenen Element, nicht zu einem Attribut; beim Binden bekommt das Element seine Attribute NodeId und Value.",
        ["More in the user manual (English)"] = "Mehr im Handbuch (englisch)",
        ["New value"] = "Neuer Wert",
        ["No discovery server answered at {0}. Is a server or a Local Discovery Server running there, and is the port open?"] = "Unter {0} hat kein Discovery-Server geantwortet. Läuft dort ein Server oder ein Local Discovery Server, und ist der Port offen?",
        ["Made the certificate {0}."] = "Zertifikat {0} angelegt.",
        ["Manuals, pictures, anything that helps to use the component. An attached Descriptor (.amlx) is embedded as one."] = "Handbücher, Bilder, alles, was beim Einsatz der Komponente hilft. Ein angehängter Descriptor (.amlx) wird als eingebetteter Descriptor aufgenommen.",
        ["Name in the certificate"] = "Name im Zertifikat",
        ["New certificate to sign with"] = "Neues Zertifikat zum Signieren",
        ["New…"] = "Neu…",
        ["No element of this document is bound to this server. Take its nodes into the document (Take into document) or bind an element of your own to a variable (Bind to element…)."] = "Kein Element dieses Dokuments ist an diesen Server gebunden. Übernimm Knoten des Servers ins Dokument ('Ins Dokument übernehmen') oder binde ein eigenes Element an eine Variable ('An Element binden…').",
        ["No model matches. Try a shorter or another search term."] = "Kein Modell passt. Versuche einen kürzeren oder anderen Suchbegriff.",
        ["None sends everything plainly, Sign protects against tampering, SignAndEncrypt also keeps it secret; the security policy names the algorithms for it. Secure in the plugin takes only Sign and SignAndEncrypt."] = "None sendet alles im Klartext, Sign schützt vor Manipulation, SignAndEncrypt hält die Daten zusätzlich geheim; die Security Policy nennt die Algorithmen dafür. 'Gesichert' im Plugin lässt nur Sign und SignAndEncrypt zu.",
        ["OPC UA FX version (OpcUaFxVersion)"] = "OPC UA FX-Version (OpcUaFxVersion)",
        ["OpcUaFxVersion is missing or empty."] = "OpcUaFxVersion fehlt oder ist leer.",
        ["Open"] = "Öffnen",
        ["Port at which this document is served (48400 unless you change it)."] = "Port, unter dem dieses Dokument als Server erreichbar ist (48400, wenn du nichts änderst).",
        ["Propose a variable of the server for each value of a model of your own, check the proposals and bind them at once; the selected part of the address space narrows the search."] = "Schlägt für jeden Wert eines eigenen Modells eine Variable des Servers vor; du prüfst die Vorschläge und bindest sie in einem Schritt. Ein im Adressraum gewählter Teil grenzt die Suche ein.",
        ["Read {0} bound value(s) of {1} into the document"] = "{0} gebundene Wert(e) von {1} ins Dokument gelesen",
        ["Reading the server's variables cancelled."] = "Lesen der Variablen des Servers abgebrochen.",
        ["Reading the server's variables failed: {0}"] = "Lesen der Variablen des Servers fehlgeschlagen: {0}",
        ["Reading the server's variables …"] = "Die Variablen des Servers werden gelesen …",
        ["Reading the variables below {0} …"] = "Die Variablen unter {0} werden gelesen …",
        ["Reading '{0}' failed: {1}"] = "Lesen von '{0}' fehlgeschlagen: {1}",
        ["Reading the arguments of '{0}' failed: {1}"] = "Lesen der Argumente von '{0}' fehlgeschlagen: {1}",
        ["RoleClass"] = "RoleClass",
        ["Save report…"] = "Bericht speichern…",
        ["Save the binding report"] = "Bericht zum Binden speichern",
        ["Saved the report to {0}."] = "Bericht gespeichert unter {0}.",
        ["Save every value the watch received, with the time it arrived, as a CSV file with semicolons, to open in a spreadsheet."] = "Speichert jeden beobachteten Wert mit der Zeit seines Eintreffens als CSV-Datei mit Semikolons, zum Öffnen in einer Tabellenkalkulation.",
        ["Save the watched values"] = "Die beobachteten Werte speichern",
        ["Save values…"] = "Werte speichern…",
        ["Saved {0} value(s) to {1}."] = "{0} Wert(e) gespeichert unter {1}.",
        ["Saving the watched values failed: {0}"] = "Speichern der beobachteten Werte fehlgeschlagen: {0}",
        ["Read from the document's OPC UA FX AML library."] = "Aus der OPC UA FX-AML-Bibliothek des Dokuments gelesen.",
        ["Relationships lead in a circle."] = "Beziehungen führen im Kreis.",
        ["Root AML file: {0}."] = "Root-AML-Datei: {0}.",
        ["Rules: "] = "Regeln: ",
        ["SHA-256 fingerprint"] = "SHA-256-Fingerabdruck",
        ["Save as UAFX Descriptor"] = "Als UAFX-Descriptor speichern",
        ["Save as UAFX Descriptor…"] = "Als UAFX-Descriptor speichern…",
        ["Saved the Descriptor {0}, signed by {1}."] = "Descriptor {0} gespeichert, signiert von {1}.",
        ["Save…"] = "Speichern…",
        ["Saving the Descriptor failed: {0}"] = "Speichern des Descriptors fehlgeschlagen: {0}",
        ["Says what an element is, apart from how it is built. An import makes every InterfaceType a RoleClass in the library RCL_ of its namespace, besides its SystemUnitClass."] = "Sagt, was ein Element ist, unabhängig davon, wie es aufgebaut ist. Ein Import macht jeden InterfaceType zu einer RoleClass in der Bibliothek RCL_ seines Namespace, zusätzlich zu seiner SystemUnitClass.",
        ["Server part"] = "Teil des Servers",
        ["Serve an element that is an instance of a UA type as an instance of that type, with the types from the NodeSets of their models. Off: plain objects and variables."] = "Stellt ein Element, das eine Instanz eines UA-Typs ist, als Instanz dieses Typs bereit, mit den Typen aus den NodeSets ihrer Modelle. Aus: einfache Objekte und Variablen.",
        ["Security"] = "Sicherheit",
        ["Servers found"] = "Gefundene Server",
        ["Server check: {0} error(s), {1} warning(s)."] = "Serverprüfung: {0} Fehler, {1} Warnung(en).",
        ["Server {0}, {1} node(s) checked: {2} error(s), {3} warning(s)."] = "Server {0}, {1} Knoten geprüft: {2} Fehler, {3} Warnung(en).",
        ["Serves the document's instance hierarchies as an OPC UA server, to try clients before the plant exists. Values follow the document; added elements need a restart. With 'simulate values' numbers swing around the document's values and booleans toggle, as in a running plant. Only this computer can connect, unless 'to the network' is ticked: then other computers may, over secured connections and only with a certificate you trusted under Clients…. Copy without server addresses saves a copy of the document without where its servers are reached (endpoints, server URIs, the ServerInstanceUri of every NodeId), to pass it on; the log names every place a host name still appears."] = "Stellt die InstanceHierarchies des Dokuments als OPC-UA-Server bereit, um Clients zu erproben, bevor es die Anlage gibt. Werte folgen dem Dokument; hinzugefügte Elemente brauchen einen Neustart. Mit 'Werte simulieren' schwanken Zahlen um die Werte des Dokuments, und boolesche Werte wechseln, wie in einer laufenden Anlage. Nur dieser Computer kann sich verbinden, außer 'im Netzwerk' ist angehakt: Dann können es auch andere Computer, über gesicherte Verbindungen und nur mit einem Zertifikat, dem du unter 'Clients…' vertraut hast. 'Kopie ohne Serveradressen' speichert eine Kopie des Dokuments ohne die Angaben, wo seine Server erreichbar sind (Endpunkte, Server-URIs, die ServerInstanceUri jeder NodeId), um sie weiterzugeben; das Protokoll nennt jede Stelle, an der noch ein Hostname vorkommt.",
        ["Short lessons in this document: models, instances, the practice plant, binding your own elements, your document as a server, a model of your own."] = "Kurze Lektionen in diesem Dokument: Modelle, Instanzen, die Übungsanlage, eigene Elemente binden, dein Dokument als Server, ein eigenes Modell.",
        ["Short lessons on the plugin, each a few minutes"] = "Kurze Lektionen zum Plugin, jede ein paar Minuten lang",
        ["Short lessons on the plugin, each a few minutes, in the open document. Steps tick themselves off when done; the control a step is about is framed in orange."] = "Kurze Lektionen zum Plugin, jede ein paar Minuten lang, im geöffneten Dokument. Erledigte Schritte haken sich selbst ab; das Bedienelement, um das es in einem Schritt geht, ist orange umrahmt.",
        ["Sign with"] = "Signieren mit",
        ["Signed by {0} on {1:yyyy-MM-dd HH:mm}: {2}."] = "Signiert von {0} am {1:yyyy-MM-dd HH:mm}: {2}.",
        ["Signed by {0}: {1}."] = "Signiert von {0}: {1}.",
        ["Start the plant the plugin brings, connect to it, take its stations into the document and follow their values live."] = "Starte die Anlage, die das Plugin mitbringt, verbinde dich mit ihr, übernimm ihre Stationen ins Dokument und verfolge ihre Werte live.",
        ["SystemUnitClass"] = "SystemUnitClass",
        ["That is how a model of your own meets a running plant: bind each element once, then read or follow its values. Ctrl+S keeps the bindings. Click Stop practice plant to end the lesson."] = "So trifft ein eigenes Modell auf eine laufende Anlage: jedes Element einmal binden, dann seine Werte lesen oder ihnen folgen. Strg+S speichert die Bindungen. Klicke auf Übungsanlage beenden, um die Lektion abzuschließen.",
        ["That is the open document; choose another name for the Descriptor."] = "Das ist das geöffnete Dokument; wähle einen anderen Namen für den Descriptor.",
        ["That is the plant: connect, take, follow. The document keeps what you took and the last values; Ctrl+S saves them. Click Stop practice plant to end the lesson."] = "Das war der ganze Ablauf: verbinden, übernehmen, verfolgen. Das Dokument behält, was du übernommen hast, und die letzten Werte; Strg+S speichert sie. Klicke auf 'Übungsanlage beenden', um die Lektion abzuschließen.",
        ["The Descriptor is not signed."] = "Der Descriptor ist nicht signiert.",
        ["The UAFX manifest is missing, doubled or departs from Annex J."] = "Das UAFX-Manifest fehlt, ist doppelt oder weicht von Anhang J ab.",
        ["The WebView2 runtime is missing or failed to start: {0} Install the Microsoft Edge WebView2 Runtime and restart the editor."] = "Die WebView2-Runtime fehlt oder ließ sich nicht starten: {0} Installiere die Microsoft Edge WebView2 Runtime und starte den Editor neu.",
        ["The XML format of AutomationML (IEC 62424). A document holds instance hierarchies, which describe the plant, and libraries of classes: system units, roles, interfaces and attribute types."] = "Das XML-Format von AutomationML (IEC 62424). Ein Dokument enthält InstanceHierarchies, die die Anlage beschreiben, und Bibliotheken von Klassen: System Units, Rollen, Schnittstellen und Attributtypen.",
        ["The document has no model of your own to bind: an InstanceHierarchy with an element for each value."] = "Das Dokument hat kein eigenes Modell zum Binden: eine InstanceHierarchy mit einem Element für jeden Wert.",
        ["The check stopped after {0} nodes; select a part of the server to check the rest."] = "Die Prüfung hat nach {0} Knoten aufgehört; wähle einen Teil des Servers, um den Rest zu prüfen.",
        ["The modeler is missing from the plugin folder ({0}). Install the plugin again."] = "Der Modeler fehlt im Plugin-Ordner ({0}). Installiere das Plugin erneut.",
        ["The search stopped after {0} variables; a variable further on may be missing. Select a part of the server in the address space to narrow it."] = "Die Suche hat nach {0} Variablen aufgehört; eine Variable weiter hinten kann fehlen. Wähle im Adressraum einen Teil des Servers, um sie einzugrenzen.",
        ["The server has no variables below {0}."] = "Der Server hat unter {0} keine Variablen.",
        ["The server has no variables to bind."] = "Der Server hat keine Variablen zum Binden.",
        ["The method takes no arguments."] = "Die Methode hat keine Argumente.",
        ["The server did not write '{0}': {1}"] = "Der Server hat '{0}' nicht geschrieben: {1}",
        ["The server lets '{0}' only be read."] = "Der Server lässt '{0}' nur lesen.",
        ["The server refused: {0}"] = "Der Server hat abgelehnt: {0}",
        ["The server runs the method at once; on a PLC it may move the plant. Call only in a plant you may change."] = "Der Server führt die Methode sofort aus; auf einer SPS kann sie die Anlage bewegen. Rufe sie nur in einer Anlage auf, die du ändern darfst.",
        ["The server says this method may not be called now."] = "Der Server sagt, dass diese Methode jetzt nicht aufgerufen werden darf.",
        ["The server takes the value at once; a PLC may act on it. Write only into a plant you may change."] = "Der Server übernimmt den Wert sofort; eine SPS kann darauf reagieren. Schreibe nur in eine Anlage, die du ändern darfst.",
        ["The top of a plant in an AutomationML document: a tree of InternalElements. New instances, nodes taken from a server and the document server all live in instance hierarchies. Nearest in OPC UA: a folder of objects below the Objects folder, as which the document server serves it."] = "Die Spitze einer Anlage in einem AutomationML-Dokument: ein Baum aus InternalElements. Neue Instanzen, vom Server übernommene Knoten und der Dokumentserver liegen alle in InstanceHierarchies. In OPC UA am nächsten: ein Ordner mit Objekten unter dem Ordner Objects; so stellt der Dokumentserver sie bereit.",
        ["The user manual on GitHub: every part of the plugin, step by step"] = "Die Kurzanleitung auf GitHub, auf Deutsch, mit Verweisen ins englische Handbuch",
        ["The watch has received no value yet."] = "Die Beobachtung hat noch keinen Wert empfangen.",
        ["This document uses CAEX {0}; OPC UA libraries need CAEX 3.0. Save a CAEX 3.0 copy… on the Namespaces tab writes one to open."] = "Dieses Dokument verwendet CAEX {0}; OPC-UA-Bibliotheken brauchen CAEX 3.0. 'CAEX-3.0-Kopie speichern…' im Reiter Namespaces legt eine Kopie an, die du öffnen kannst.",
        ["To look without writing into the document: select a variable in the address space and click Watch (view only). Its value appears in the list below the tree, with its status and when it arrived."] = "Nur ansehen, ohne ins Dokument zu schreiben: Wähle im Adressraum eine Variable und klicke auf 'Beobachten (nur ansehen)'. Der Wert erscheint in der Liste unter dem Baum, mit Status und Empfangszeit.",
        ["Types of the server imports the types of one of its namespaces. Take into document creates elements for the checked nodes, with their NodeIds, UA types and values; Count nodes says how many first. Bind to element gives an element of yours a node's address; Bind model does it for every value of a model of yours at once. Read values into document reads the values of the bound elements once, Keep document values live writes every change into them, Watch only shows values in the list below. Write value and Call method act on the running server, after asking."] = "'Typen des Servers' importiert die Typen eines seiner Namespaces. 'Ins Dokument übernehmen' legt für die angehakten Knoten Elemente an, mit ihren NodeIds, UA-Typen und Werten; 'Knoten zählen' sagt vorher, wie viele es werden. 'An Element binden' gibt einem deiner Elemente die Adresse eines Knotens; 'Modell binden' tut das für alle Werte eines deiner Modelle auf einmal. 'Werte ins Dokument lesen' liest die Werte der gebundenen Elemente einmal, 'Dokumentwerte live halten' schreibt jede Änderung in sie, 'Beobachten' zeigt Werte nur in der Liste unten an. 'Wert schreiben' und 'Methode aufrufen' wirken nach Rückfrage auf den laufenden Server.",
        ["Value of the model"] = "Wert des Modells",
        ["Values of the model and their variables"] = "Werte des Modells und ihre Variablen",
        ["Variable of the server"] = "Variable des Servers",
        ["Variables without a value of the model"] = "Variablen ohne Wert des Modells",
        ["Took {0} from the discovery server; Connect connects to it."] = "{0} vom Discovery-Server übernommen; 'Verbinden' verbindet damit.",
        ["Use"] = "Übernehmen",
        ["Users"] = "Benutzer",
        ["Warning"] = "Warnung",
        ["Words in common"] = "Gemeinsame Wörter",
        ["Value now"] = "Wert jetzt",
        ["Values of the type {0} cannot be typed in."] = "Werte vom Typ {0} lassen sich nicht eingeben.",
        ["Values with {0} dimensions cannot be typed in."] = "Werte mit {0} Dimensionen lassen sich nicht eingeben.",
        ["Write"] = "Schreiben",
        ["Write a value into the selected variable of the server, after asking; a PLC may act on it at once."] = "Schreibt nach Rückfrage einen Wert in die gewählte Variable des Servers; eine SPS kann sofort darauf reagieren.",
        ["Write a value into the server"] = "Einen Wert in den Server schreiben",
        ["Write value…"] = "Wert schreiben…",
        ["Writing '{0}' failed: {1}"] = "Schreiben von '{0}' fehlgeschlagen: {1}",
        ["Writing '{0}' …"] = "'{0}' wird geschrieben …",
        ["Wrote {0} into '{1}'."] = "{0} in '{1}' geschrieben.",
        ["The chain of a signing certificate is incomplete or not trusted."] = "Die Kette eines signierenden Zertifikats ist unvollständig oder nicht vertrauenswürdig.",
        ["The document as an AML container for OPC UA FX offline engineering (OPC 10000-83): a manifest, the files you attach, your signature."] = "Das Dokument als AML-Container für das Offline-Engineering mit OPC UA FX (OPC 10000-83): ein Manifest, die Dateien, die du anhängst, deine Signatur.",
        ["The document uses no OPC UA FX AML library, so the Descriptor will not be an OPC UA FX information model as OPC 10000-83 asks; give the version it should adhere to."] = "Das Dokument nutzt keine OPC UA FX-AML-Bibliothek, der Descriptor ist also kein OPC UA FX-Informationsmodell, wie OPC 10000-83 es verlangt; gib die Version an, der er folgen soll.",
        ["The file is not an AML container (an OPC package)."] = "Die Datei ist kein AML-Container (OPC-Paket).",
        ["The identifier is not a URI, such as urn:company:plant:component."] = "Die Kennung ist keine URI wie urn:firma:anlage:komponente.",
        ["The password of the file, if it has one."] = "Das Passwort der Datei, falls sie eines hat.",
        ["The version is up to four numbers from 0 to 65535 separated by points, such as 1.0.0.0."] = "Die Version besteht aus bis zu vier Zahlen von 0 bis 65535, durch Punkte getrennt, etwa 1.0.0.0.",
        ["Trust"] = "Vertrauen",
        ["Trust signer…"] = "Unterzeichner vertrauen…",
        ["Trust the certificate that signed this Descriptor, after comparing its fingerprint with the sender."] = "Dem Zertifikat vertrauen, das diesen Descriptor signiert hat, nachdem du seinen Fingerabdruck mit dem Absender verglichen hast.",
        ["Trust {0}?"] = "{0} vertrauen?",
        ["UAFX Descriptor (*.amlx)|*.amlx"] = "UAFX-Descriptor (*.amlx)|*.amlx",
        ["UAFX Descriptor (*.amlx)|*.amlx|All files (*.*)|*.*"] = "UAFX-Descriptor (*.amlx)|*.amlx|Alle Dateien (*.*)|*.*",
        ["UAFX Descriptor ▾"] = "UAFX-Descriptor ▾",
        ["UAFX Descriptors (OPC 10000-83): save the document as a signed AML container for offline engineering, or check one you received."] = "UAFX-Descriptoren (OPC 10000-83): das Dokument als signierten AML-Container für das Offline-Engineering speichern oder einen erhaltenen prüfen.",
        ["Up to four numbers separated by points: Major.Minor.Build.SubBuild."] = "Bis zu vier Zahlen, durch Punkte getrennt: Major.Minor.Build.SubBuild.",
        ["Version (DescriptorVersion)"] = "Version (DescriptorVersion)",
        ["Windows certificate store"] = "Windows-Zertifikatspeicher",
        ["Write this document as a UAFX Descriptor: an AML container with a manifest, the files you attach and your digital signature."] = "Schreibt dieses Dokument als UAFX-Descriptor: ein AML-Container mit Manifest, den Dateien, die du anhängst, und deiner digitalen Signatur.",
        ["Writing the Descriptor …"] = "Der Descriptor wird geschrieben …",
        ["[Content_Types].xml lists an extension no file has."] = "[Content_Types].xml nennt eine Dateiendung, die keine Datei hat.",
        ["[Content_Types].xml lists the extension .{0}, which no file has (OPC 10000-83 7.6)."] = "[Content_Types].xml nennt die Endung .{0}, die keine Datei hat (OPC 10000-83 7.6).",
        ["_depth"] = "_Tiefe",
        ["_Password"] = "_Passwort",
        ["_User"] = "_Benutzer",
        ["A child declaration in angle brackets, such as <DeviceName>: it stands for any number of children of its type. A MandatoryPlaceholder needs at least one."] = "Eine Kinddeklaration in spitzen Klammern, etwa <DeviceName>, die für beliebig viele Kindknoten ihres Typs steht. Ein MandatoryPlaceholder braucht mindestens einen.",
        ["A companion specification or your own model as NodeSet2.xml, or drop the files here; required models are found in the NodeSet folders."] = "Eine Companion Specification oder dein eigenes Modell als NodeSet2.xml, oder zieh die Dateien hierher; benötigte Modelle werden in den NodeSet-Ordnern gesucht.",
        ["A Mandatory child of the type is missing."] = "Ein Kindelement, das der Typ als Mandatory deklariert, fehlt.",
        ["A MandatoryPlaceholder of the type has no instance."] = "Ein MandatoryPlaceholder des Typs hat keine Instanz.",
        ["A message from the modeler could not be read: {0}"] = "Eine Nachricht des Modelers ließ sich nicht lesen: {0}",
        ["A namespace of the document; its NodeSet is the file it was imported from, or one in a NodeSet folder"] = "Ein Namespace des Dokuments; sein NodeSet ist die Datei, aus der er importiert wurde, oder eine in einem NodeSet-Ordner",
        ["The UA base model is built into the modeler; it is not edited there."] = "Das UA-Basismodell ist im Modeler eingebaut; dort wird es nicht bearbeitet.",
        ["A NodeSet converted before is taken from a cache instead of being converted again (seconds instead of a quarter minute). This empties the cache."] = "Ein schon einmal umgewandeltes NodeSet kommt aus einem Cache, statt erneut umgewandelt zu werden (Sekunden statt einer Viertelminute). Dies leert den Cache.",
        ["A part of the address space a server defines for a purpose, browsed on its own."] = "Ein Teil des Adressraums, den ein Server für einen bestimmten Zweck festlegt und der sich für sich allein durchsuchen lässt.",
        ["A placeholder (a name in angle brackets) stands for any number of children; name the ones to create."] = "Ein Platzhalter (ein Name in spitzen Klammern) steht für beliebig viele Kindelemente; benenne die, die angelegt werden sollen.",
        ["A placeholder declaration (<Name>) was copied into an instance."] = "Eine Platzhalter-Deklaration (<Name>) wurde in eine Instanz kopiert.",
        ["A small variable that describes its parent, held by HasProperty: engineering units, a range, a serial number."] = "Eine kleine Variable, die ihren Elternknoten beschreibt und über HasProperty an ihm hängt: Maßeinheiten, ein Wertebereich, eine Seriennummer.",
        ["A TechnicalResource refers to the OPC UA object that represents it, a ProcessOperator to the method that executes it."] = "Eine TechnicalResource verweist auf das OPC-UA-Objekt, das sie darstellt, ein ProcessOperator auf die Methode, die ihn ausführt.",
        ["A type meant only to be derived from. OPC UA creates no instances of it; pick a concrete subtype."] = "Ein Typ, der nur zum Ableiten gedacht ist. OPC UA bildet keine Instanzen davon; wähle einen konkreten Subtyp.",
        ["A UA type or instance in the notation of OPC 10000-3. Shapes: rectangle Object, rounded rectangle Variable, ellipse Method; types are shaded. Lines: one stroke HasComponent, two strokes HasProperty, two filled heads HasTypeDefinition, two hollow heads HasSubtype, an open head other hierarchical references, a filled head the others. Letters give the ModellingRule: M Mandatory, O Optional, MP and OP placeholders, E ExposesItsArray."] = "Ein UA-Typ oder eine UA-Instanz in der Notation von OPC 10000-3. Formen: Rechteck Object, abgerundetes Rechteck Variable, Ellipse Method; Typen sind schattiert. Linien: ein Strich HasComponent, zwei Striche HasProperty, zwei gefüllte Spitzen HasTypeDefinition, zwei hohle Spitzen HasSubtype, eine offene Spitze andere hierarchische Referenzen, eine gefüllte Spitze die übrigen. Buchstaben geben die ModellingRule an: M Mandatory, O Optional, MP und OP Platzhalter, E ExposesItsArray.",
        ["A VDI 3682 element links to an OPC UA element that does not exist."] = "Ein VDI-3682-Element verweist auf ein OPC-UA-Element, das es nicht gibt.",
        ["a GUID"] = "eine GUID",
        ["a number, such as 1.5"] = "eine Zahl, etwa 1,5",
        ["a time, such as 2026-11-24T10:00:00Z"] = "eine Zeit, etwa 2026-11-24T10:00:00Z",
        ["a value of this type cannot be typed in"] = "ein Wert dieses Typs lässt sich nicht eingeben",
        ["a whole number"] = "eine ganze Zahl",
        ["abstract"] = "abstrakt",
        ["Abstract type"] = "Abstrakter Typ",
        ["Account of uacloudlibrary.opcfoundation.org"] = "Konto bei uacloudlibrary.opcfoundation.org",
        ["Add"] = "Hinzufügen",
        ["Add missing Mandatory children"] = "Fehlende Mandatory-Kindelemente hinzufügen",
        ["Add NodeSet folder…"] = "NodeSet-Ordner hinzufügen…",
        ["Add {0} Mandatory child(ren)?"] = "{0} Mandatory-Kindelement(e) hinzufügen?",
        ["Added to what the selected element holds, with IDs of their own, on every Apply."] = "Wird bei jedem Übernehmen zu dem hinzugefügt, was das ausgewählte Element enthält, mit eigenen IDs.",
        ["Added {0} Mandatory child(ren) to {1} instance(s). Press Ctrl+S to save."] = "{0} Mandatory-Kindelement(e) zu {1} Instanz(en) hinzugefügt. Drücke Strg+S, um zu speichern.",
        ["Address space"] = "Adressraum",
        ["Address space reloaded."] = "Adressraum neu geladen.",
        ["Address space: check the parts to take; right click for how much below them. ✓ marks nodes already in the document. F5 reloads."] = "Adressraum: Hake die Teile an, die du übernehmen willst; mit einem Rechtsklick legst du fest, wie viel darunter dazugehört. ✓ markiert Knoten, die schon im Dokument sind. F5 lädt neu.",
        ["Adds"] = "Fügt hinzu",
        ["Add…"] = "Hinzufügen…",
        ["After importing a newer version of a companion specification: add the Mandatory children the types now declare. Nothing existing is changed."] = "Nach dem Import einer neueren Version einer Companion Specification: die Mandatory-Kindelemente hinzufügen, die die Typen jetzt deklarieren. Nichts Bestehendes wird geändert.",
        ["Again"] = "Noch einmal",
        ["All"] = "Alle",
        ["All instances already have the Mandatory children of their types."] = "Alle Instanzen haben schon die Mandatory-Kindelemente ihrer Typen.",
        ["All lessons"] = "Alle Lektionen",
        ["All nodes a server offers, reached from its Objects folder along references."] = "Alle Knoten, die ein Server anbietet, erreicht vom Objects-Ordner aus entlang von Referenzen.",
        ["Already in the document"] = "Schon im Dokument",
        ["AML-UA-XSLT"] = "AML-UA-XSLT",
        ["An import is running; import {0} when it is done."] = "Ein Import läuft; importiere {0}, wenn er fertig ist.",
        ["An imported OPC UA model, as it was"] = "Ein importiertes OPC-UA-Modell, wie es war",
        ["An information model for a domain, published by the OPC Foundation with a partner organisation: DI, Machinery, Robotics and many more."] = "Ein Informationsmodell für ein Fachgebiet, von der OPC Foundation gemeinsam mit einer Partnerorganisation veröffentlicht: DI, Machinery, Robotics und viele mehr.",
        ["An InstanceHierarchy of their own. Every Apply replaces it, the rest of the document stays as it is."] = "Eine eigene InstanceHierarchy. Jedes Übernehmen ersetzt sie; der Rest des Dokuments bleibt, wie er ist.",
        ["An InternalLink connects reference interfaces that do not belong together (RefClassConnectsToPath)."] = "Ein InternalLink verbindet Referenzschnittstellen, die nicht zusammengehören (RefClassConnectsToPath).",
        ["An InternalLink points to an interface that does not exist."] = "Ein InternalLink zeigt auf eine Schnittstelle, die es nicht gibt.",
        ["An OPC UA information model as an XML file (UANodeSet): its types, instances and the models it requires."] = "Ein OPC-UA-Informationsmodell als XML-Datei (UANodeSet): seine Typen, Instanzen und die Modelle, die es benötigt.",
        ["Annex A"] = "Annex A",
        ["another document was opened"] = "ein anderes Dokument wurde geöffnet",
        ["Ask GitHub for the current list now instead of using today's."] = "Die aktuelle Liste jetzt bei GitHub abfragen, statt die von heute zu nutzen.",
        ["any text"] = "beliebiger Text",
        ["at _most"] = "_höchstens",
        ["At most nodes"] = "Höchstzahl der Knoten",
        ["AutomationML (*.aml)|*.aml"] = "AutomationML (*.aml)|*.aml",
