        ["Bound {0} to '{1}'."] = "{0} an '{1}' gebunden.",
        ["Bring OPC UA into this document"] = "OPC UA in dieses Dokument holen",
        ["BrowseName"] = "BrowseName",
        ["Builds on"] = "Basiert auf",
