        ["Depth"] = "Tiefe",
        ["check"] = "prüfen",
        ["cannot be reached from a Root AML file through relationships (OPC 10000-83 7.5.2)."] = "ist über Beziehungen von keiner Root-AML-Datei aus erreichbar (OPC 10000-83 7.5.2).",
        ["certificate {0} is a CA certificate; a Descriptor is signed by an end entity (OPC 10000-83 Table 3)."] = "Zertifikat {0} ist ein CA-Zertifikat; ein Descriptor wird von einer Endinstanz signiert (OPC 10000-83 Tabelle 3).",
