        ["has no type definition."] = "hat keine Typdefinition.",
        ["has no UAFX manifest: no file whose root element is DescriptorInfo (OPC 10000-83 7.3.2)."] = "hat kein UAFX-Manifest: keine Datei mit dem Wurzelelement DescriptorInfo (OPC 10000-83 7.3.2).",
