        ["Saving {0}"] = "Speichern von {0}",
        ["Says whether a child declared by a type appears in each instance: Mandatory always, Optional when chosen, placeholders as often as you name children for them."] = "Legt fest, ob ein von einem Typ deklarierter Kindknoten in jeder Instanz vorkommt: Mandatory immer, Optional nach Wahl, Platzhalter so oft, wie du Kindknoten für sie benennst.",
        ["Search"] = "Suchen",
