        ["Select"] = "Auswählen",
        ["Select a namespace for its details, its types and what builds on it."] = "Wähle einen Namespace, um seine Details, seine Typen und das, was auf ihm aufbaut, zu sehen.",
        ["Select an InstanceHierarchy or an element in the editor first."] = "Wähle zuerst im Editor eine InstanceHierarchy oder ein Element.",
        ["Select the DI namespace in the list. On the right you see what it brings (ObjectTypes, VariableTypes, DataTypes, ReferenceTypes), what it builds on and which elements use its types."] = "Wähle den DI-Namespace in der Liste. Rechts siehst du, was er mitbringt (ObjectTypes, VariableTypes, DataTypes, ReferenceTypes), worauf er aufbaut und welche Elemente seine Typen verwenden.",
        ["Select the element in the editor"] = "Element im Editor auswählen",
        ["Selected {0} in the editor."] = "{0} im Editor ausgewählt.",
        ["Selection"] = "Auswahl",
        ["Serve"] = "Bereitstellen",
        ["Serve this document as an OPC UA server, connect to it, take a part of it back, keep its values live."] = "Stelle dieses Dokument als OPC-UA-Server bereit, verbinde dich damit, übernimm einen Teil davon zurück und halte seine Werte live.",
        ["Serve this document: its instance hierarchies become an OPC UA server that only this computer reaches. It stands in for a real plant here."] = "Stelle dieses Dokument bereit: Seine InstanceHierarchies werden zu einem OPC-UA-Server, den nur dieser Computer erreicht. Er steht hier für eine echte Anlage.",
        ["Server"] = "Server",
        ["Serving {0} node(s) of this document at {1}, to other computers too, to trusted clients only (Clients…), with simulated values."] = "{0} Knoten dieses Dokuments werden unter {1} im Netzwerk bereitgestellt, nur für Clients, denen du unter 'Clients…' vertraust, mit simulierten Werten.",
        ["Serving {0} node(s) of this document at {1}, to other computers too, to trusted clients only (Clients…)."] = "{0} Knoten dieses Dokuments werden unter {1} im Netzwerk bereitgestellt, nur für Clients, denen du unter 'Clients…' vertraust.",
        ["Serving {0} node(s) of this document at {1}, to this computer only, with simulated values."] = "{0} Knoten dieses Dokuments werden unter {1} bereitgestellt, nur für diesen Computer, mit simulierten Werten.",
        ["Serving {0} node(s) of this document at {1}, to this computer only."] = "{0} Knoten dieses Dokuments werden unter {1} bereitgestellt, nur für diesen Computer.",
