        ["Start"] = "Starten",
        ["Start a new model with this namespace URI."] = "Ein neues Modell mit dieser Namespace-URI anlegen.",
        ["Start an OPC UA server whose address space is this document's instance hierarchies; values follow the document, added elements need a restart."] = "Einen OPC-UA-Server starten, dessen Adressraum die InstanceHierarchies dieses Dokuments bilden; Werte folgen dem Dokument, hinzugefügte Elemente brauchen einen Neustart.",
        ["Starting a new model"] = "Anlegen eines neuen Modells",
