        ["Language"] = "Sprache",
        ["As Windows"] = "Wie Windows",
        ["The language of the plugin and the modeler; it changes when the editor starts again."] = "Die Sprache des Plugins und des Modelers; sie wechselt beim nächsten Start des Editors.",
        ["The language changes when the editor starts again."] = "Die Sprache wechselt beim nächsten Start des Editors.",
        ["Practice plant"] = "Übungsanlage",
        ["Stop practice plant"] = "Übungsanlage beenden",
        ["Start the MPS 500 learning factory of the Helmut Schmidt University as an OPC UA server on this computer, with simulated values, to connect to and practise on. Click again to stop it."] = "Startet die Lernfabrik MPS 500 der Helmut-Schmidt-Universität als OPC-UA-Server auf diesem Computer, mit simulierten Werten, zum Verbinden und Üben. Ein zweiter Klick beendet sie.",
        ["The practice plant is missing from the plugin folder ({0}). Install the plugin again."] = "Die Übungsanlage fehlt im Ordner des Plugins ({0}). Installiere das Plugin erneut.",
        ["The ports {0} to {1} are in use; the practice plant cannot start."] = "Die Ports {0} bis {1} sind belegt; die Übungsanlage kann nicht starten.",
        ["Starting the practice plant …"] = "Übungsanlage wird gestartet …",
        ["The practice plant runs: the MPS 500 learning factory, {0} node(s) with simulated values, at {1}. Connect to it."] = "Die Übungsanlage läuft: die Lernfabrik MPS 500, {0} Knoten mit simulierten Werten, unter {1}. Verbinde dich mit ihr.",
        ["Starting the practice plant failed: {0}"] = "Starten der Übungsanlage fehlgeschlagen: {0}",
        ["Practice plant stopped."] = "Übungsanlage beendet.",
